"""IK benchmark on random *reachable* poses (targets generated by FK of random joint vectors).

    python scripts/bench_ik.py --n 1000
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path

import numpy as np

from pnp.ik.kinematics import SerialChain
from pnp.ik.solver import DLSSolver, IKConfig
from pnp.sim.scene import build_model

VARIANTS = {
    "DLS, single descent (no restarts)": IKConfig(restarts=0),
    "DLS + up to 20 random restarts": IKConfig(restarts=20),
    "ablation: clip joints instead of wrap, 20 restarts": IKConfig(restarts=20, wrap_full_turn=False),
}


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--n", type=int, default=1000)
    ap.add_argument("--seed", type=int, default=0)
    ap.add_argument("--out", type=Path, default=Path("results"))
    a = ap.parse_args()
    chain = SerialChain.from_mujoco(build_model())
    tasks_rng = np.random.default_rng(a.seed)
    tasks = [(chain.fk(chain.random_q(tasks_rng)), chain.random_q(tasks_rng)) for _ in range(a.n)]
    out = {}
    for name, cfg in VARIANTS.items():
        solver, rng = DLSSolver(chain, cfg), np.random.default_rng(a.seed + 1)
        rs = [solver.solve(T, seed, rng=rng) for T, seed in tasks]
        ok = np.array([r.success for r in rs])
        pe = np.array([r.pos_err for r in rs])[ok] * 1e3
        re = np.rad2deg(np.array([r.rot_err for r in rs])[ok])
        it = np.array([r.iters for r in rs])
        tt = np.array([r.time_s for r in rs]) * 1e3
        at = np.array([r.attempts for r in rs])[ok]
        out[name] = {
            "n": a.n, "success_rate": float(ok.mean()),
            "pos_err_mm_median": float(np.median(pe)), "pos_err_mm_max": float(pe.max()),
            "rot_err_deg_median": float(np.median(re)), "rot_err_deg_max": float(re.max()),
            "iters_median": float(np.median(it)), "iters_p95": float(np.percentile(it, 95)),
            "time_ms_median": float(np.median(tt)), "time_ms_p95": float(np.percentile(tt, 95)),
            "attempts_mean_successful": float(at.mean()),
        }
    a.out.mkdir(parents=True, exist_ok=True)
    (a.out / "ik_benchmark.json").write_text(json.dumps(out, indent=1))
    lines = ["| Variant | Success | Pos err med / max (mm) | Rot err med / max (deg) | Iters med / p95 | "
             "Time med / p95 (ms) |", "|---|---|---|---|---|---|"]
    for k, s in out.items():
        lines.append(f"| {k} | {100*s['success_rate']:.1f}% | "
                     f"{s['pos_err_mm_median']:.4f} / {s['pos_err_mm_max']:.4f} | "
                     f"{s['rot_err_deg_median']:.5f} / {s['rot_err_deg_max']:.4f} | {s['iters_median']:.0f} / "
                     f"{s['iters_p95']:.0f} | {s['time_ms_median']:.1f} / {s['time_ms_p95']:.1f} |")
    md = "\n".join(lines)
    (a.out / "ik_benchmark.md").write_text(md + "\n")
    print(md)


if __name__ == "__main__":
    main()
